# -*- coding: utf-8 -*-
"""
Data models for the multi-agent offline KG-RAG experiment.
"""

from __future__ import annotations

from pydantic import BaseModel, Field, field_validator

from schemas import DetectionResult, GraphWarning, TypedEntity


class VulnerabilityHypothesis(BaseModel):
    """Verifiable vulnerability hypothesis generated by the orchestrator."""

    hypothesis_id: str = Field(description="Hypothesis ID, e.g. H1")
    cwe_id: str = Field(default="", description="Candidate CWE ID")
    risk_type: str = Field(default="", description="Risk type")
    reason: str = Field(default="", description="Why this hypothesis should be verified")
    assigned_agent: str = Field(
        default="VulnerabilityVerifier",
        description="Suggested downstream agent name",
    )


class OrchestratorPlan(BaseModel):
    """Orchestrator planning output."""

    entities: list[TypedEntity] = Field(default_factory=list)
    semantic_summary: str = Field(default="")
    domain: str = Field(default="Other")
    initial_risk_assessment: str = Field(
        default="uncertain",
        description="safe / suspicious / vulnerable / uncertain",
    )
    context_possible_cwes: list[str] = Field(default_factory=list)
    vulnerability_hypotheses: list[VulnerabilityHypothesis] = Field(default_factory=list)


class AgentTask(BaseModel):
    """Task dispatched to a downstream agent."""

    task_id: str
    hypothesis_id: str = ""
    assigned_agent: str
    target_cwe: str = ""
    risk_type: str = ""
    task_goal: str
    entities: list[TypedEntity] = Field(default_factory=list)
    domain: str = "Other"


class CodeEvidence(BaseModel):
    """Source-code evidence or counter-evidence."""

    evidence_type: str = Field(
        description="dangerous_operation / missing_check / defense / neutral"
    )
    line_or_snippet: str = ""
    analysis: str = ""


class AgentVerificationReport(BaseModel):
    """Verification report produced by a downstream agent."""

    agent_name: str
    task_id: str = ""
    hypothesis_id: str = ""
    target_cwe: str = ""
    graph_evidence: list[GraphWarning] = Field(default_factory=list)
    code_evidence: list[CodeEvidence] = Field(default_factory=list)
    defense_evidence: list[CodeEvidence] = Field(default_factory=list)
    verdict: str = Field(
        default="uncertain",
        description="supported / not_supported / uncertain",
    )
    confidence: float = 0.5
    recommended_cwe: str = ""
    summary: str = ""
    retrieval_request: str = Field(
        default="",
        description="Concise KG query request when a second retrieval pass is needed",
    )
    verification_round: int = 1
    previous_verdict: str = ""
    previous_summary: str = ""
    raw_output: str = Field(default="", description="Raw LLM output for replay/debugging")
    parse_error: str = Field(default="", description="Parse failure reason, empty on success")

    @field_validator("confidence", mode="before")
    @classmethod
    def normalize_confidence(cls, value):
        if isinstance(value, str):
            text = value.strip().lower()
            label_map = {
                "high": 0.9,
                "medium": 0.5,
                "moderate": 0.5,
                "low": 0.3,
                "certain": 0.9,
                "uncertain": 0.5,
            }
            if text in label_map:
                return label_map[text]
        return value


class AgentFusionDecision(BaseModel):
    """Final fusion decision."""

    fusion_trace: str = ""
    is_vulnerable: bool
    confidence: float = 0.5
    cwe_id: str = ""
    vulnerability_type: str = ""
    explanation: str = ""
    affected_lines: list[str] = Field(default_factory=list)


class AgentDetectionResult(DetectionResult):
    """Detection result compatible with the original evaluator plus agent traces."""

    orchestrator_plan: OrchestratorPlan | None = None
    agent_tasks: list[AgentTask] = Field(default_factory=list)
    agent_reports: list[AgentVerificationReport] = Field(default_factory=list)
    final_fusion_trace: str = ""
    raw_orchestrator_output: str = Field(default="", description="Raw orchestrator output")
    raw_fusion_output: str = Field(default="", description="Raw final-judge output")
